package dns

import("context";"fmt";"net";"strings";"time")
type ProtocolLatency struct{Protocol string `json:"protocol"`;RTT time.Duration `json:"rtt"`;Success bool `json:"success"`;Error string `json:"error,omitempty"`}
func ProbeProtocolLatency(ctx context.Context,protocol,address string,timeout time.Duration)ProtocolLatency{protocol=strings.ToLower(strings.TrimSpace(protocol));address=strings.TrimSpace(address);result:=ProtocolLatency{Protocol:protocol};if protocol!="tcp"&&protocol!="udp"{result.Error=fmt.Sprintf("unsupported protocol: %s",protocol);return result};if address==""||len(address)>2048{result.Error="address is invalid";return result};if timeout<=0{timeout=5*time.Second};if timeout>30*time.Second{timeout=30*time.Second};if ctx==nil{result.Error="context is required";return result};if err:=ctx.Err();err!=nil{result.Error=err.Error();return result};start:=time.Now();conn,err:=(&net.Dialer{Timeout:timeout}).DialContext(ctx,protocol,address);result.RTT=time.Since(start);if err!=nil{result.Error=err.Error();return result};if err:=conn.Close();err!=nil{result.Error=err.Error();return result};result.Success=true;return result}
